import { MeshBasicNodeMaterial } from 'three/webgpu';
import { gsap } from 'gsap';
import * as primitives from '@/primitives';
import * as text from '@/text';

export default function createNode(config, ctx) {
  const group = new ctx.THREE.Group();

  // Plane geometry based on image aspect (512x320 => 1.6:1)
  const geometry = new ctx.THREE.PlaneGeometry(1.6, 1);
  const material = new MeshBasicNodeMaterial();
  const mesh = new ctx.THREE.Mesh(geometry, material);
  group.add(mesh);

  // Load texture asynchronously
  ctx.textureLoader.loadTexture(config.imageUrl).then((tex) => {
    material.map = tex;
    material.needsUpdate = true;
  });

  // Apply rotation & scale from config (scenePosition is applied by adapter)
  if (config.rotation) group.rotation.set(...config.rotation);
  if (config.scale) group.scale.set(...config.scale);

  // Store active GSAP timelines for cleanup
  const activeTimelines = [];

  // Event handlers container
  const handlers = {};

  // Hover lift (rise‑in) effect
  handlers.hover = {
    enter: () => {
      const tl = gsap.timeline();
      tl.to(group.position, {
        y: group.position.y + 0.15,
        duration: 0.7,
        ease: 'power3.out',
      });
      activeTimelines.push(tl);
    },
    leave: () => {
      const tl = gsap.timeline();
      tl.to(group.position, {
        y: group.position.y - 0.15,
        duration: 0.3,
        ease: 'power3.in',
      });
      activeTimelines.push(tl);
    },
  };

  // Click: press‑down animation + emit navigation event
  handlers.click = () => {
    const tl = gsap.timeline();
    tl.to(group.scale, {
      x: group.scale.x * 0.97,
      y: group.scale.y * 0.97,
      z: group.scale.z * 0.97,
      duration: 0.12,
      ease: 'back.out(1.7)',
    })
      .to(
        group.scale,
        {
          x: group.scale.x / 0.97,
          y: group.scale.y / 0.97,
          z: group.scale.z / 0.97,
          duration: 0.2,
          ease: 'power2.out',
        },
        '+=0.05'
      )
      .call(() => {
        ctx.emit('hub-journal.select', {});
      });
    activeTimelines.push(tl);
  };

  group.userData.handlers = handlers;

  // Apply any cinematic primitives defined in config
  const primitiveInstances = [];
  if (Array.isArray(config.cinematicPrimitives)) {
    for (const prim of config.cinematicPrimitives) {
      const instance = ctx.primitives[prim.name](group, prim.params);
      primitiveInstances.push(instance);
    }
  }

  // Cleanup routine
  group.userData.cleanup = () => {
    // Dispose geometry & material
    geometry.dispose();
    material.dispose();

    // Kill GSAP timelines
    activeTimelines.forEach((t) => t.kill());

    // Cleanup primitives
    primitiveInstances.forEach((p) => {
      if (p && typeof p.cleanup === 'function') p.cleanup();
    });
  };

  return group;
}
